#include <stdio.h>
#include <stdlib.h>

#define MAXN 100005
#define MAXLOG 20
#define INF 1000000000

typedef struct {
    int u, v, w;
} Edge;

int up[MAXLOG][MAXN];
int minEdge[MAXLOG][MAXN];
int depth[MAXN];

int head[MAXN], to[2 * MAXN], nxt[2 * MAXN], wt[2 * MAXN], ec;

int parent[MAXN], rnk[MAXN];
int queue[MAXN];

int cmp(const void *a, const void *b) {
    Edge *ea = (Edge *)a;
    Edge *eb = (Edge *)b;
    return eb->w - ea->w;
}

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

int unite(int a, int b) {
    a = find(a);
    b = find(b);
    if (a == b) return 0;
    if (rnk[a] < rnk[b]) {
        int t = a;
        a = b;
        b = t;
    }
    parent[b] = a;
    if (rnk[a] == rnk[b]) rnk[a]++;
    return 1;
}

void addEdge(int u, int v, int w) {
    to[ec] = v;
    wt[ec] = w;
    nxt[ec] = head[u];
    head[u] = ec++;
}

int query(int u, int v) {
    int ans = INF;

    if (depth[u] < depth[v]) {
        int t = u;
        u = v;
        v = t;
    }

    int diff = depth[u] - depth[v];
    for (int k = 0; k < MAXLOG; k++) {
        if (diff & (1 << k)) {
            if (minEdge[k][u] < ans) ans = minEdge[k][u];
            u = up[k][u];
        }
    }

    if (u == v) return ans;

    for (int k = MAXLOG - 1; k >= 0; k--) {
        if (up[k][u] != up[k][v]) {
            if (minEdge[k][u] < ans) ans = minEdge[k][u];
            if (minEdge[k][v] < ans) ans = minEdge[k][v];
            u = up[k][u];
            v = up[k][v];
        }
    }

    if (minEdge[0][u] < ans) ans = minEdge[0][u];
    if (minEdge[0][v] < ans) ans = minEdge[0][v];

    return ans;
}

int main() {
    int N, B;
    scanf("%d %d", &N, &B);

    Edge *edges = (Edge *)malloc(B * sizeof(Edge));
    for (int i = 0; i < B; i++) {
        scanf("%d %d %d", &edges[i].u, &edges[i].v, &edges[i].w);
    }

    qsort(edges, B, sizeof(Edge), cmp);

    for (int i = 1; i <= N; i++) {
        parent[i] = i;
        rnk[i] = 0;
        head[i] = -1;
    }

    ec = 0;

    for (int i = 0; i < B; i++) {
        if (unite(edges[i].u, edges[i].v)) {
            addEdge(edges[i].u, edges[i].v, edges[i].w);
            addEdge(edges[i].v, edges[i].u, edges[i].w);
        }
    }

    for (int i = 1; i <= N; i++) {
        up[0][i] = i;
        minEdge[0][i] = INF;
    }

    int qh = 0, qt = 0;
    queue[qt++] = 1;
    depth[1] = 0;
    up[0][1] = 1;

    while (qh < qt) {
        int v = queue[qh++];

        for (int e = head[v]; e != -1; e = nxt[e]) {
            int u = to[e];
            if (u == up[0][v]) continue;

            up[0][u] = v;
            minEdge[0][u] = wt[e];
            depth[u] = depth[v] + 1;
            queue[qt++] = u;
        }
    }

    for (int k = 1; k < MAXLOG; k++) {
        for (int v = 1; v <= N; v++) {
            int mid = up[k - 1][v];
            up[k][v] = up[k - 1][mid];

            int a = minEdge[k - 1][v];
            int b = minEdge[k - 1][mid];
            minEdge[k][v] = (a < b ? a : b);
        }
    }

    int C;
    scanf("%d", &C);

    while (C--) {
        int X, Y;
        scanf("%d %d", &X, &Y);
        printf("%d\n", query(X, Y));
    }

    free(edges);
    return 0;
}
